function resolveNode(path: string, hops = 0): { node: VfsNode; parent?: VfsNode; name?: string } {
  if (hops > 40) throw new Error('ELOOP: too many symbolic links');
  const parts = normalizePath(path);
  let current = rootNode;
  let parent: VfsNode | undefined = undefined;
  let name: string | undefined = undefined;

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    if (!current.isDir || !current.children) {
      throw new Error(`ENOTDIR: not a directory, '${part}'`);
    }

    const next = current.children.get(part);
    if (!next) {
      if (i === parts.length - 1) {
        return { node: null as any, parent: current, name: part };
      }
      throw new Error(`ENOENT: no such file or directory, '${path}'`);
    }

    if (next.target !== undefined) {
      // Symlink
      const remaining = parts.slice(i + 1).join('/');
      const targetPath = next.target.startsWith('/') ? `${next.target}/${remaining}` : `${next.target}/${remaining}`;
      return resolveNode(targetPath, hops + 1);
    }

    parent = current;
    name = part;
    current = next;
  }

  return { node: current, parent, name };
}

function writeToRingBuffer(sab: SharedArrayBuffer, text: string) {
  const int32 = new Int32Array(sab, 0, 4);
  const capacity = int32[3];
  const data = new Uint8Array(sab, 16, capacity);
  const encoded = new TextEncoder().encode(text);

  let offset = 0;
  while (offset < encoded.length) {
    const writeHead = Atomics.load(int32, 1);
    const readHead = Atomics.load(int32, 2);

    const available = writeHead >= readHead
      ? capacity - (writeHead - readHead) - 1
      : readHead - writeHead - 1;

    if (available <= 0) break;

    const toWrite = Math.min(encoded.length - offset, available);
    let cur = writeHead;
    for (let i = 0; i < toWrite; i++) {
      data[cur] = encoded[offset + i];
      cur = (cur + 1) % capacity;
    }

    Atomics.store(int32, 1, cur);
    Atomics.store(int32, 0, 1); // FLAG_DATA
    Atomics.notify(int32, 0);
    offset += toWrite;
  }
}

function createTar(files: Record<string, Uint8Array>): Uint8Array {
  const blocks: Uint8Array[] = [];

  for (const [name, data] of Object.entries(files)) {
    const header = new Uint8Array(512);
    // Write name (0..100)
    const nameBytes = new TextEncoder().encode(name);
    header.set(nameBytes.subarray(0, 100), 0);

    // Write mode: "0000644\0" (100..108)
    header.set(new TextEncoder().encode('0000644\0'), 100);

    // Write size in octal: 11 digits + space/null (124..136)
    const sizeOctal = data.length.toString(8).padStart(11, '0') + ' ';
    header.set(new TextEncoder().encode(sizeOctal), 124);

    // Typeflag: '0' (156)
    header[156] = 48; // '0'

    // Compute checksum (148..156) with 8 spaces
    header.set(new TextEncoder().encode('        '), 148);
    let chksum = 0;
    for (let i = 0; i < 512; i++) {
      chksum += header[i];
    }
    const chksumStr = chksum.toString(8).padStart(6, '0') + '\0 ';
    header.set(new TextEncoder().encode(chksumStr), 148);

    blocks.push(header);

    // Data blocks padded to 512
    const dataPadded = new Uint8Array(Math.ceil(data.length / 512) * 512);
    dataPadded.set(data, 0);
    blocks.push(dataPadded);
  }

  // Two 512-byte zero blocks at end of tar
  blocks.push(new Uint8Array(1024));

  const totalLen = blocks.reduce((acc, b) => acc + b.length, 0);
  const result = new Uint8Array(totalLen);
  let cur = 0;
  for (const b of blocks) {
    result.set(b, cur);
    cur += b.length;
  }
  return result;
}

function setupReconnectionHandshake(): void {
  if (typeof BroadcastChannel === 'undefined') return;

  const channel = new BroadcastChannel('buddhilive-sandbox-sw');

  channel.onmessage = (event) => {
    const { type, port } = event.data;
    if (type === 'port:register' && typeof port === 'number') {
      globalPortRegistry.register(port);
      channel.postMessage({ type: 'port:registered', port });
    } else if (type === 'port:unregister' && typeof port === 'number') {
      globalPortRegistry.unregister(port);
    } else if (type === 'sw:ping') {
      channel.postMessage({
        type: 'sw:pong',
        ports: globalPortRegistry.list(),
      });
    }
  };

  // Announce SW activation
  channel.postMessage({
    type: 'sw:ready',
    ports: globalPortRegistry.list(),
  });
}

async function bridgeRequest(
  portNumber: number,
  request: Request,
  relativePath: string
): Promise<Response> {
  const portEntry = globalPortRegistry.get(portNumber);

  if (!portEntry) {
    return new Response(
      `<html><body><h2>503 Service Unavailable</h2><p>No virtual HTTP server listening on port ${portNumber}.</p></body></html>`,
      {
        status: 503,
        statusText: 'Service Unavailable',
        headers: {
          'Content-Type': 'text/html; charset=utf-8',
          'Cross-Origin-Opener-Policy': 'same-origin',
          'Cross-Origin-Embedder-Policy': 'require-corp',
        },
      }
    );
  }

  // If a MessagePort exists for forwarding to WASM Worker
  if (portEntry.messagePort) {
    const channel = new MessageChannel();
    const headersMap: Record<string, string> = {};
    request.headers.forEach((v, k) => {
      headersMap[k] = v;
    });

    const bodyBuffer = request.method !== 'GET' && request.method !== 'HEAD'
      ? await request.arrayBuffer()
      : null;

    return new Promise<Response>((resolve) => {
      const timeout = setTimeout(() => {
        resolve(
          new Response(
            `<html><body><h2>504 Gateway Timeout</h2><p>Port ${portNumber} timed out responding.</p></body></html>`,
            { status: 504, headers: { 'Content-Type': 'text/html' } }
          )
        );
      }, 10000);

      channel.port1.onmessage = (event) => {
        clearTimeout(timeout);
        const { status, statusText, headers, body } = event.data;
        const res = new Response(body, {
          status: status || 200,
          statusText: statusText || 'OK',
          headers: {
            ...headers,
            'Cross-Origin-Opener-Policy': 'same-origin',
            'Cross-Origin-Embedder-Policy': 'require-corp',
          },
        });
        resolve(res);
      };

      portEntry.messagePort!.postMessage(
        {
          type: 'http:request',
          port: portNumber,
          path: relativePath,
          method: request.method,
          headers: headersMap,
          body: bodyBuffer,
          replyPort: channel.port2,
        },
        [channel.port2]
      );
    });
  }

  // Default synthetic response if virtual port is registered without custom handler
  return new Response(
    `<!DOCTYPE html><html><head><title>Preview ${portNumber}</title></head><body><h1>Preview Server on Port ${portNumber}</h1><p>Status: Active</p><p>Path: ${relativePath}</p></body></html>`,
    {
      status: 200,
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cross-Origin-Opener-Policy': 'same-origin',
        'Cross-Origin-Embedder-Policy': 'require-corp',
      },
    }
  );
}

