pub fn normalize_path(path: &str) -> Vec<String> {
    let mut parts = Vec::new();
    for seg in path.split('/') {
        if seg.is_empty() || seg == "." {
            continue;
        }
        if seg == ".." {
            parts.pop();
        } else {
            parts.push(seg.to_string());
        }
    }
    parts
}

fn resolve_path_internal(table: &InodeTable, path: &str, hops: usize) -> Result<u64> {
    if hops > MAX_SYMLINK_HOPS {
        return Err(SandboxError::TooManyLinks);
    }

    let parts = normalize_path(path);
    let mut current_id = ROOT_INODE_ID;

    for (idx, part) in parts.iter().enumerate() {
        let node = table.get(current_id)?;
        match &node.kind {
            INodeKind::Directory { children } => {
                current_id = *children
                    .get(part)
                    .ok_or_else(|| SandboxError::NotFound(path.to_string()))?;
            }
            INodeKind::Symlink { target } => {
                let remaining = &parts[idx..];
                let new_path = if target.starts_with('/') {
                    format!("{}/{}", target, remaining.join("/"))
                } else {
                    format!("{}/{}", target, remaining.join("/"))
                };
                return resolve_path_internal(table, &new_path, hops + 1);
            }
            INodeKind::File { .. } => {
                return Err(SandboxError::NotADirectory(part.to_string()));
            }
        }
    }

    // Check if the final node itself is a symlink that should be dereferenced if asked
    let final_node = table.get(current_id)?;
    if let INodeKind::Symlink { target } = &final_node.kind {
        return resolve_path_internal(table, target, hops + 1);
    }

    Ok(current_id)
}

pub fn resolve_path(table: &InodeTable, path: &str) -> Result<u64> {
    resolve_path_internal(table, path, 0)
}

fn test_ring_buffer_close() {
    let mut ring = StdioRingBuffer::new(512);
    ring.close();

    let flag = i32::from_le_bytes(ring.as_slice()[OFFSET_FLAG..OFFSET_FLAG + 4].try_into().unwrap());
    assert_eq!(flag, FLAG_CLOSED);
}

fn test_ring_buffer_wraparound() {
    let capacity = 32;
    let mut ring = StdioRingBuffer::new(capacity);

    // Write 20 bytes
    let part1 = b"01234567890123456789";
    ring.write_bytes(part1);

    // Read 15 bytes
    let mut buf1 = [0u8; 15];
    let r1 = ring.read_bytes(&mut buf1);
    assert_eq!(r1, 15);
    assert_eq!(&buf1, &part1[..15]);

    // Write 20 more bytes (causes circular wraparound)
    let part2 = b"abcdefghijklmnopqrst";
    let w2 = ring.write_bytes(part2);
    assert!(w2 > 0);

    // Drain all remaining
    let mut out = vec![0u8; 64];
    let r2 = ring.read_bytes(&mut out);
    assert!(r2 > 0);
}

fn test_ring_buffer_write_read_roundtrip() {
    let mut ring = StdioRingBuffer::new(1024);
    let message = b"Hello from Rust WASM ring buffer test!";

    let written = ring.write_bytes(message);
    assert_eq!(written, message.len());

    let slice = ring.as_slice();
    let flag = i32::from_le_bytes(slice[OFFSET_FLAG..OFFSET_FLAG + 4].try_into().unwrap());
    assert_eq!(flag, FLAG_DATA);

    let mut out = [0u8; 128];
    let read = ring.read_bytes(&mut out);
    assert_eq!(read, message.len());
    assert_eq!(&out[..read], message);

    // After draining, flag should reset to empty
    let flag_after = i32::from_le_bytes(ring.as_slice()[OFFSET_FLAG..OFFSET_FLAG + 4].try_into().unwrap());
    assert_eq!(flag_after, FLAG_EMPTY);
}

fn test_port_manager_listen_and_close() {
    let mut pm = PortManager::new();

    pm.listen(3000).expect("Listen on 3000");
    assert!(pm.is_listening(3000));
    assert_eq!(pm.active_ports(), vec![3000]);

    // Listening again on same port should return error (already in use)
    let err = pm.listen(3000);
    assert!(err.is_err());

    // Close port
    pm.close(3000).expect("Close 3000");
    assert!(!pm.is_listening(3000));
    assert!(pm.active_ports().is_empty());
}

